#!/usr/bin/env python3
"""P9-3.2 independent diagnostic probes. No source writes or acceptance effects.
Native: python P9-3.2-independent-stress-tests.py --repo /path/to/repo --output /new/run
Qualified: extract full audit bundle, then use --qualified-audit --output /new/run.
Qualified mode uses declared older providers and is not native conformance.
"""
import argparse,sys,json,hashlib,importlib.metadata,platform
from pathlib import Path
parser=argparse.ArgumentParser()
mode=parser.add_mutually_exclusive_group(required=True)
mode.add_argument('--repo',type=Path)
mode.add_argument('--qualified-audit',action='store_true')
parser.add_argument('--output',type=Path,required=True)
args=parser.parse_args()
if args.output.exists():parser.error('output already exists; preserve original evidence')
args.output.mkdir(parents=True)
if args.qualified_audit:
 sys.path.insert(0,str(Path(__file__).resolve().parent/'p932_audit'))
 import bootstrap
else:
 repo=args.repo.resolve()
 if not (repo/'src/pygrc/models/grc_v4_geometry.py').is_file():parser.error('not a supported repository source root')
 sys.path[:0]=[str(repo/'src'),str(repo)]
"""Independent prospective P9-3.2 probes; no runtime support or gate changes.
Imported only after a native or explicitly qualified dependency environment is selected.
"""
from pathlib import Path
from dataclasses import replace
from fractions import Fraction as F
from decimal import Decimal, localcontext
import hashlib,itertools,json,math,random,sys,time,traceback
from unittest.mock import patch
from pygrc.models import grc_v4_geometry as g
from pygrc.models.grc_v4_codec import canonical_json_bytes,decode_canonical_json,payload_identity
from pygrc.models.grc_v4_state import GRCV4AuthoritativeState as State,FrozenJSONMap
from pygrc.models.grc_v4_profile import list_supported_profiles
from tests.models.test_grc_v4_geometry import stage_reference_fixture as refmake,stage_inputs_fixture as stagemake

ROWS=[]; OBS=[]
def check(group,name,fn):
 if len(ROWS)%40==0:print('progress',len(ROWS),group,flush=True)
 try:
  detail=fn(); ROWS.append({'group':group,'name':name,'passed':True,'detail':detail})
 except Exception as e:
  ROWS.append({'group':group,'name':name,'passed':False,'error':repr(e),'traceback':traceback.format_exc()})
def rejects(fn,part=None):
 try: fn()
 except (TypeError,ValueError,UnicodeError) as e:
  if part is not None: assert part in str(e),(part,str(e))
  return type(e).__name__
 raise AssertionError('unexpected acceptance')
def det(a):
 n=len(a)
 if n==0:return F(1)
 if n==1:return F(a[0][0])
 return sum(((-1)**j*F(a[0][j])*det([row[:j]+row[j+1:] for row in a[1:]]) for j in range(n)), F(0))
def is_spd(a):
 return all(det([list(row[:i]) for row in a[:i]])>0 for i in range(1,len(a)+1))
def graph(n):
 return g.GRCV4Graph(('u','v'),tuple(g.OrientedEdge(f'e{i}','u','v') for i in range(n)))
def scalar_affine(ref,inc,gain):
 return [[F(a)+F(gain)*F(b) for a,b in zip(r,s)] for r,s in zip(ref,inc)]
def zero(n):return tuple((0.0,)*n for _ in range(n))
def canonical_equal(a,b):assert canonical_json_bytes(a)==canonical_json_bytes(b)
def rehash(cache):
 cache['cache_id']='grcv4-derived-geometry-cache-sha256:'+hashlib.sha256(canonical_json_bytes(cache['payload'])).hexdigest()
 return canonical_json_bytes(cache)
def star_decimal(graph,values):
 with localcontext() as ctx:
  ctx.prec=100;n=len(values)
  raw=[Decimal.from_float(float(x)) for x in values]
  stars=[[i for i,e in enumerate(graph.oriented_edges) if e.tail_node_id==v or e.head_node_id==v] for v in graph.live_node_ids]
  mul=[sum(i in star for star in stars) for i in range(n)]
  a=[[Decimal(0) for _ in range(n)] for _ in range(n)]
  for star in stars:
   local=[raw[i]/Decimal(mul[i]).sqrt() for i in star]
   for i,ei in enumerate(star):
    for j,ej in enumerate(star):a[ei][ej]+=local[i]*local[j]
  return tuple(tuple(float(x) for x in r) for r in a)
def near_matrix(a,b):
 assert len(a)==len(b)
 for i,(r,s) in enumerate(zip(a,b)):
  for j,(x,y) in enumerate(zip(r,s)):
   assert math.isclose(x,y,rel_tol=3e-15,abs_tol=2e-15),(i,j,x,y)


def run(out):
 start=time.time(); rng=random.Random(932001)
 # Independent exact principal-minor oracle, distinct from production Bareiss.
 for n in range(1,5):
  for k in range(36):
   a=[[0.0]*n for _ in range(n)]
   for i in range(n):
    for j in range(i,n):a[i][j]=a[j][i]=rng.randint(-12,16)/4
   if k%3==0:
    for i in range(n):a[i][i]=sum(abs(x) for j,x in enumerate(a[i]) if j!=i)+.25
   expected=is_spd(a)
   def probe(a=a,n=n,expected=expected):
    if expected:g.OneFormHodge(graph(n),a)
    else:rejects(lambda:g.OneFormHodge(graph(n),a),'positive definite')
    return {'exact_positive':expected}
   check('exact_positive_domain',f'{n}-{k}',probe)
 # Exact old Cholesky counterexamples + scaled positive controls.
 for scale in [2.0**-900,2.0**-200,2.0,2.0**200,2.0**900]:
  for d in [scale,math.nextafter(scale,0.0)]:
   for order in [0,1]:
    a=[[scale,scale],[scale,d]]
    if order:a=[r[::-1] for r in a[::-1]]
    check('exact_positive_domain',f'rank-boundary-{scale.hex()}-{d.hex()}-{order}',lambda a=a:rejects(lambda:g.OneFormHodge(graph(2),a),'positive definite'))
 for scale in [5e-324,1e-308,2.0**-500,1.0,2.0**500,1e308]:
  check('exact_positive_domain',f'positive-scale-{scale.hex()}',lambda s=scale:g.OneFormHodge(graph(2),[[s,0.0],[0.0,s]]).matrix)
 # Exact affine expression and retained binary64 image must each be positive.
 for n in range(1,5):
  for k in range(24):
   weights={f'e{i}':float(2**(i%3)) for i in range(n)}
   gain=[0.0,.25,.5,1.0,2.0][k%5]
   base=[[float((-1 if i%2 else 1)*2**40) if i==j else 0.0 for j in range(n)] for i in range(n)]
   ref=refmake(graph=graph(n),weights=weights,base=base,gain=gain)
   inc=[[0.0]*n for _ in range(n)]
   for i in range(n):
    for j in range(i,n):inc[i][j]=inc[j][i]=rng.randint(-12,12)/4
   mathematical=scalar_affine(ref.pairings.one_form.matrix,inc,gain)
   stored=[[a+gain*b for a,b in zip(r,s)] for r,s in zip(ref.pairings.one_form.matrix,inc)]
   expected=is_spd(mathematical) and is_spd(stored)
   def probe(ref=ref,inc=inc,stored=stored,expected=expected):
    tensor=g.K4Tensor(ref.graph,ref.K4_base,inc)
    call=lambda:g.H_profile(tensor,reference=ref,context=ref.context,profile=ref.profile)
    if expected:assert call().one_form_hodge.matrix==tuple(tuple(r) for r in stored)
    else:rejects(call,'positive definite')
    return {'exact_and_stored_positive':expected}
   check('affine_domain_and_values',f'{n}-{k}',probe)
 # High scale baseline independent from increment.
 for b in [1e308,-1e308,0.0]:
  for gain in [0.0,.5,2.0]:
   def probe(b=b,gain=gain):
    r=refmake(base=[[b,0.0],[0.0,b]],gain=gain)
    x=g.H_profile(g.K4Tensor(r.graph,r.K4_base,((2.0,1.0),(1.0,2.0))),reference=r,profile=r.profile,context=r.context)
    assert x.one_form_hodge.matrix==((2.0+2*gain,gain),(gain,3.0+2*gain))
   check('affine_domain_and_values',f'baseline-{b}-{gain}',probe)
 # Affine exact-positive-but-rounds-zero and exact-zero/negative neighbors.
 for sign in [-1,0,1]:
